static void settle(thrum_bee *bee, int result) {
    pthread_mutex_lock(&bee->mu);
    if (bee->start_result < 0) {
        bee->start_result = result == THRUM_LINK_CLOSED ? THRUM_LINK_FAILED : result;
        if (result == THRUM_LINK_CLOSED && !bee->error[0])
            snprintf(bee->error, sizeof bee->error, "the link closed before humd admitted the bee");
    }
    if (!bee->ended) {
        bee->ended = 1;
        bee->result = result;
    }
    pthread_cond_broadcast(&bee->cond);
    pthread_mutex_unlock(&bee->mu);
}

static const char *string_of(const cJSON *obj, const char *key) {
    const cJSON *v = cJSON_GetObjectItemCaseSensitive(obj, key);
    return cJSON_IsString(v) ? v->valuestring : NULL;
}

static void receive(thrum_bee *bee, const char *line) {
    cJSON *msg = cJSON_Parse(line);
    if (!cJSON_IsObject(msg)) {
        cJSON_Delete(msg);
        return;
    }
    const char *chi = string_of(msg, "chi");
    if (chi) {
        thrum_tone_fn fn = NULL;
        void *user = NULL;
        pthread_mutex_lock(&bee->mu);
        if (!table_get(bee->by_sid, bee->n_sid, string_of(msg, "sid"), &fn, &user))
            table_get(bee->by_chi, bee->n_chi, chi, &fn, &user);
        if (!fn) {
            fn = bee->any;
            user = bee->any_user;
        }
        pthread_mutex_unlock(&bee->mu);
        if (fn) fn(bee, msg, user);
        cJSON_Delete(msg);
        return;
    }
    const char *link = string_of(msg, "link");
    if (!link) {
        cJSON_Delete(msg);
        return;
    }
    if (strcmp(link, "ready") == 0) {
        const cJSON *version = cJSON_GetObjectItemCaseSensitive(msg, "linkVersion");
        pthread_mutex_lock(&bee->mu);
        if (!cJSON_IsNumber(version) || (int)version->valuedouble != THRUM_LINK_VERSION) {
            char got[32];
            snprintf(got, sizeof got, "%d", cJSON_IsNumber(version) ? (int)version->valuedouble : -1);
            snprintf(bee->error, sizeof bee->error,
                     "hum speaks link version %s and this client %d; rebuild the hive against the installed hum",
                     got, THRUM_LINK_VERSION);
            bee->failed = 1;
            kill(bee->pid, SIGKILL);
        } else {
            snprintf(bee->id, sizeof bee->id, "%s", string_of(msg, "bee") ? string_of(msg, "bee") : "");
        }
        pthread_mutex_unlock(&bee->mu);
    } else if (strcmp(link, "nestled") == 0 || strcmp(link, "astray") == 0) {
        int nestled = link[0] == 'n';
        event_handler fns[THRUM_EVENTS_MAX];
        size_t n;
        pthread_mutex_lock(&bee->mu);
        if (nestled && bee->start_result < 0) {
            bee->start_result = 0;
            pthread_cond_broadcast(&bee->cond);
        }
        n = nestled ? bee->n_nestled : bee->n_astray;
        memcpy(fns, nestled ? bee->nestled : bee->astray, n * sizeof *fns);
        pthread_mutex_unlock(&bee->mu);
        for (size_t i = 0; i < n; i++) fns[i].fn(bee, fns[i].user);
    } else if (strcmp(link, "advisory") == 0) {
        thrum_advisory a = {
            .code = string_of(msg, "code") ? string_of(msg, "code") : "",
            .message = string_of(msg, "message") ? string_of(msg, "message") : "",
            .from = string_of(msg, "from") ? string_of(msg, "from") : "",
            .fields = cJSON_GetObjectItemCaseSensitive(msg, "fields"),
        };
        advisory_handler fns[THRUM_EVENTS_MAX];
        size_t n;
        pthread_mutex_lock(&bee->mu);
        n = bee->n_advisory;
        memcpy(fns, bee->advisory, n * sizeof *fns);
        pthread_mutex_unlock(&bee->mu);
        for (size_t i = 0; i < n; i++) fns[i].fn(bee, &a, fns[i].user);
    } else if (strcmp(link, "refused") == 0) {
        pthread_mutex_lock(&bee->mu);
        set_error(bee, "%s%s", string_of(msg, "error") ? string_of(msg, "error") : "refused", NULL);
        pthread_mutex_unlock(&bee->mu);
    }
    cJSON_Delete(msg);
}

static void *read_link(void *arg) {
    thrum_bee *bee = arg;
    FILE *in = fdopen(bee->from_link, "r");
    if (in) {
        char *line = NULL;
        size_t cap = 0;
        while (getline(&line, &cap, in) > 0) receive(bee, line);
        free(line);
        fclose(in);
    } else {
        close(bee->from_link);
    }
    bee->from_link = -1;

    int status = 0;
    while (waitpid(bee->pid, &status, 0) < 0 && errno == EINTR) {
    }
    int code = WIFEXITED(status) ? WEXITSTATUS(status) : -1;

    pthread_mutex_lock(&bee->mu);
    int failed = bee->failed, closing = bee->closing;
    pthread_mutex_unlock(&bee->mu);
    int result;
    if (code == THRUM_LINK_REFUSED) {
        result = THRUM_LINK_REFUSED;
    } else if (failed) {
        result = THRUM_LINK_FAILED;
    } else if (code == THRUM_LINK_CLOSED && closing) {
        result = THRUM_LINK_CLOSED;
    } else {
        char how[64];
        if (code < 0) snprintf(how, sizeof how, "was killed");
        else snprintf(how, sizeof how, "exited %d%s", code, code == THRUM_LINK_USAGE ? ", a usage error" : "");
        pthread_mutex_lock(&bee->mu);
        set_error(bee, "the link %s%s", how, NULL);
        pthread_mutex_unlock(&bee->mu);
        result = THRUM_LINK_FAILED;
    }
    settle(bee, result);
    return NULL;
}

int thrum_bee_start(thrum_bee *bee) {
    pthread_mutex_lock(&bee->mu);
    if (bee->started) {
        pthread_mutex_unlock(&bee->mu);
        return THRUM_LINK_FAILED;
    }
    bee->started = 1;
    pthread_mutex_unlock(&bee->mu);
    ignore_sigpipe();

    char hum[PATH_MAX];
    if (bee->hum) {
        snprintf(hum, sizeof hum, "%s", bee->hum);
    } else if (thrum_hum_cli(hum, sizeof hum) != 0) {
        set_error(bee, "could not find hum: set %s%s", THRUM_HUM_CLI_ENV, NULL);
        settle(bee, THRUM_LINK_FAILED);
        return THRUM_LINK_FAILED;
    }

    int to[2], from[2];
    if (pipe(to) != 0) {
        set_error(bee, "could not make a pipe: %s%s", strerror(errno), NULL);
        settle(bee, THRUM_LINK_FAILED);
        return THRUM_LINK_FAILED;
    }
    if (pipe(from) != 0) {
        set_error(bee, "could not make a pipe: %s%s", strerror(errno), NULL);
        close(to[0]);
        close(to[1]);
        settle(bee, THRUM_LINK_FAILED);
        return THRUM_LINK_FAILED;
    }
    fcntl(to[1], F_SETFD, FD_CLOEXEC);
    fcntl(from[0], F_SETFD, FD_CLOEXEC);

    posix_spawn_file_actions_t actions;
    posix_spawn_file_actions_init(&actions);
    posix_spawn_file_actions_adddup2(&actions, to[0], STDIN_FILENO);
    posix_spawn_file_actions_adddup2(&actions, from[1], STDOUT_FILENO);
    posix_spawn_file_actions_addclose(&actions, to[0]);
    posix_spawn_file_actions_addclose(&actions, to[1]);
    posix_spawn_file_actions_addclose(&actions, from[0]);
    posix_spawn_file_actions_addclose(&actions, from[1]);
    char *argv[] = {hum, "bee", "link", "--hive", bee->hive, "--as", bee->as, "--role", bee->role, NULL};
    int spawned = posix_spawnp(&bee->pid, hum, &actions, NULL, argv, environ);
    posix_spawn_file_actions_destroy(&actions);
    close(to[0]);
    close(from[1]);
    if (spawned != 0) {
        set_error(bee, "could not run %s: %s", hum, strerror(spawned));
        close(to[1]);
        close(from[0]);
        settle(bee, THRUM_LINK_FAILED);
        return THRUM_LINK_FAILED;
    }
    pthread_mutex_lock(&bee->wmu);
    bee->to_link = to[1];
    pthread_mutex_unlock(&bee->wmu);
    bee->from_link = from[0];

    write_hello(bee, bee->hello);
    if (pthread_create(&bee->reader, NULL, read_link, bee) != 0) {
        set_error(bee, "could not start the reader thread%s%s", NULL, NULL);
        kill(bee->pid, SIGKILL);
        waitpid(bee->pid, NULL, 0);
        settle(bee, THRUM_LINK_FAILED);
        return THRUM_LINK_FAILED;
    }
    bee->reading = 1;

    pthread_mutex_lock(&bee->mu);
    while (bee->start_result < 0) pthread_cond_wait(&bee->cond, &bee->mu);
    int result = bee->start_result;
    pthread_mutex_unlock(&bee->mu);
    return result;
}

int thrum_bee_send(thrum_bee *bee, const cJSON *tone) {
    return write_json(bee, tone);
}

int thrum_bee_hello(thrum_bee *bee, const cJSON *patch) {
    return write_hello(bee, patch);
}

int thrum_bee_close(thrum_bee *bee) {
    pthread_mutex_lock(&bee->mu);
    bee->closing = 1;
    int started = bee->started;
    pthread_mutex_unlock(&bee->mu);
    pthread_mutex_lock(&bee->wmu);
    if (bee->to_link >= 0) {
        close(bee->to_link);
        bee->to_link = -1;
    }
    pthread_mutex_unlock(&bee->wmu);
    if (!started) {
        pthread_mutex_lock(&bee->mu);
        bee->started = 1;
        pthread_mutex_unlock(&bee->mu);
        settle(bee, THRUM_LINK_CLOSED);
    }
    return thrum_bee_wait(bee);
}

int thrum_bee_wait(thrum_bee *bee) {
    pthread_mutex_lock(&bee->mu);
    while (!bee->ended) pthread_cond_wait(&bee->cond, &bee->mu);
    int result = bee->result;
    pthread_mutex_unlock(&bee->mu);
    return result;
}

const char *thrum_bee_id(thrum_bee *bee) {
    return bee->id;
}

const char *thrum_bee_error(thrum_bee *bee) {
    return bee->error;
}

void thrum_bee_free(thrum_bee *bee) {
    if (!bee) return;
    if (bee->reading) {
        int ended;
        pthread_mutex_lock(&bee->mu);
        ended = bee->ended;
        pthread_mutex_unlock(&bee->mu);
        if (!ended) thrum_bee_close(bee);
        pthread_join(bee->reader, NULL);
    }
    if (bee->to_link >= 0) close(bee->to_link);
    pthread_mutex_destroy(&bee->mu);
    pthread_mutex_destroy(&bee->wmu);
    pthread_cond_destroy(&bee->cond);
    for (size_t i = 0; i < bee->n_chi; i++) free(bee->by_chi[i].chi);
    free(bee->by_chi);
    for (size_t i = 0; i < bee->n_sid; i++) free(bee->by_sid[i].chi);
    free(bee->by_sid);
    cJSON_Delete(bee->hello);
    free(bee->hive);
    free(bee->as);
    free(bee->role);
    free(bee->hum);
    free(bee);
}
